import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { LandingPage } from './pages/LandingPage';
import { CompanionsPage } from './pages/CompanionsPage';
import { RoomPage } from './pages/RoomPage';
import { VideoCallPage } from './pages/VideoCallPage';
import { getUserId } from './utils/userSession';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
const App = () => {
  const [page, setPage] = useState('landing');
  const [selectedCompanion, setSelectedCompanion] = useState(null);
  const [roomId, setRoomId] = useState('');
  const [userId, setUserId] = useState('');

  useEffect(() => {
    const id = getUserId();
    setUserId(id);
    console.log('✅ App initialized with user ID:', id);
  }, []);

  const navigateTo = (page) => {
    console.log('📍 Navigating to:', page);
    setPage(page);
  };

  const handleSelectCompanion = (companion) => {
    console.log('✅ Selected companion:', companion.name);
    setSelectedCompanion(companion);
    navigateTo('room');
  };

  const handleJoinRoom = (id) => {
    console.log('✅ Joining room:', id);
    setRoomId(id);
    navigateTo('video');
  };

  const handleEndCall = () => {
    console.log('📞 Call ended');
    setSelectedCompanion(null);
    setRoomId('');
    navigateTo('companions');
  };

  const handleBack = () => {
    if (page === 'companions') {
      navigateTo('landing');
    } else if (page === 'room') {
      navigateTo('companions');
    }
  };

  const renderPage = () => {
    switch (page) {
      case 'landing':
        return <LandingPage onNavigate={() => navigateTo('companions')} />;
      
      case 'companions':
        return <CompanionsPage onSelectCompanion={handleSelectCompanion} />;
      
      case 'room':
        return (
          <RoomPage
            companion={selectedCompanion}
            userId={userId}
            onJoinRoom={handleJoinRoom}
            onBack={() => navigateTo('companions')}
          />
        );
      
      case 'video':
        return (
          <VideoCallPage
            companion={selectedCompanion}
            roomId={roomId}
            userId={userId}
            onEndCall={handleEndCall}
          />
        );
      
      default:
        return <LandingPage onNavigate={() => navigateTo('companions')} />;
    }
  };

  return (
    <div className="min-h-screen">
      <Navbar 
        showNav={page !== 'video'} 
        onBack={handleBack}
        showBackButton={page === 'room'}
        currentPage={page}
        onNavigate={navigateTo}
      />
      <div className={page !== 'video' ? 'pt-16' : ''}>
        {renderPage()}
      </div>
    </div>
  );
};

export default App;
